from pathlib import Path
import json,csv,sqlite3
r=Path(__file__).parent;a=json.loads((r/'results.json').read_text());c=sqlite3.connect('file:'+str(Path.home()/'.local/share/opencode/opencode.db')+'?mode=ro',uri=True);events=[]
for l in (Path.home()/'.local/share/opencode/task-learning/routing.jsonl').read_text().splitlines():
 try:events.append(json.loads(l))
 except:pass
rows=[]
for x in a:
 counts={};firstCloud=None;lateLocal=0;fallback=next((e for e in events if e.get('sessionID')==x['sessionId'] and e.get('event')=='local-fallback'),None)
 for(v,)in c.execute("select data from session_message where session_id=? and type='assistant' order by time_created",[x['sessionId']]):
  d=json.loads(v);p=d.get('model',{}).get('providerID');t=d.get('tokens') or {};active=any(t.get(k,0) for k in ['input','output','reasoning']) or t.get('cache',{}).get('read',0)
  if active:counts[p]=counts.get(p,0)+1
  if p=='openrouter' and firstCloud is None:firstCloud=round((d.get('time',{}).get('created',x['startedAt'])-x['startedAt'])/1000,3)
  if p=='evo-agent' and active and fallback and d.get('time',{}).get('created',0)>fallback['at']:lateLocal+=1
 u=x['usage'];delta=x.get('deltas') or {};row={'id':x['id'],'name':x['name'],'seconds':x['seconds'],'cloud_input':u['fresh']+u['cached'],'cloud_output':u['output']+u['reasoning'],'cloud_cached':u['cached'],'cloud_cost':u['cost'],'local_completed_calls':counts.get('evo-agent',0),'cloud_calls':u['requests'],'first_cloud_seconds':firstCloud,'fallback_seconds':round(fallback['elapsedMs']/1000,3) if fallback else None,'stale_local_blocked':sum(e.get('sessionID')==x['sessionId'] and e.get('event')=='stale-local-request-blocked' for e in events),'completed_local_requests_started_after_handoff':lateLocal,'input_delta':delta.get('input'),'output_delta':delta.get('output'),'cost_delta':delta.get('cost'),'time_delta':delta.get('seconds'),'over_60s':x['targetExceeded'],'reply_ok':x['ok']};rows.append(row)
with (r/'comparison.csv').open('w') as f:w=csv.DictWriter(f,fieldnames=rows[0]);w.writeheader();w.writerows(rows)
(r/'comparison.json').write_text(json.dumps(rows,indent=2));lines=['# Fifteen natural-route tests after handoff and polling fixes','', 'Original 10 workloads followed by the previously prepared 5 new workloads, in order. No prompt contains a model-selection instruction. Production Telegram message handler and actual delivery; isolated diagnostic sessions. Per-test token/cost/time reports were delivered immediately. Tests 12 and 15 are explicitly synthetic forensic drills, not actual security incidents.','', '| Test | Time | Local completed calls | Cloud calls | Cloud input | Cloud output | Cloud cost | Delta vs matched natural reference |','|---|---:|---:|---:|---:|---:|---:|---|']
for x in rows:
 d='N/A' if x['cost_delta'] is None else f"input {x['input_delta']:+,}; output {x['output_delta']:+,}; ${x['cost_delta']:+.8f}; {x['time_delta']:+.1f}s"
 lines.append(f"| {x['id']}. {x['name']} | {x['seconds']:.1f}s | {x['local_completed_calls']} | {x['cloud_calls']} | {x['cloud_input']:,} | {x['cloud_output']:,} | ${x['cloud_cost']:.8f} | {d} |")
lines+=['',f"Replies received {sum(x['reply_ok'] for x in rows)}/{len(rows)}. Over 60s design target: {sum(x['over_60s'] for x in rows)}. Worst observed {max(x['seconds'] for x in rows):.1f}s. Total cloud cost ${sum(x['cloud_cost'] for x in rows):.8f}.",'', 'The 60-second target is not a hard abort. Output includes reasoning and tool-call generation. References exist for tests 4,5,10 from the previous natural-route run; other savings are not claimed. Provider/cache behavior, live evidence and model-selected tool paths can differ. Reply completion is not correctness certification. Local completed call counts exclude blocked/failed requests without tokens and exclude direct classifier/preprocessor calls.','', 'Confirmed fixes: stale local requests already constructed before session model switch are rejected by the gateway and retried on the switched model, preserving completed tool results. Poll failures now reach bounded exponential backoff and respect Telegram retry-after. Configured environment-expanded keys return 200 on both local model endpoints; a literal env placeholder is not a valid credential test. No credential rotation or arbitrary 40KB payload cap was applied.','', 'Known prior inventory-filter issue is assessed separately; synthetic expected values are in quality-oracles.json. Full responses are in results.json.']
(r/'REPORT.md').write_text('\n'.join(lines)+'\n');print(json.dumps({'completed':len(rows),'worst_s':max(x['seconds'] for x in rows),'cloud_cost':sum(x['cloud_cost'] for x in rows),'late_local_after_handoff':sum(x['completed_local_requests_started_after_handoff'] for x in rows)}))
